"""Shared input and template utilities for the independent book renderer."""
import os, re, sys, json, zipfile
from pathlib import Path


def resource(name):
    p = Path(__file__).parent / 'data' / name
    try:
        return p.read_text(encoding='utf-8')
    except (NotADirectoryError, FileNotFoundError):
        with zipfile.ZipFile(sys.argv[0]) as z:
            return z.read('data/' + name).decode('utf-8')


SCHEMA = json.loads(resource('options.json'))

class BookError(Exception):
    pass

class YAMLFailure(Exception):
    def __init__(self, detail, line=1, col=1):
        self.detail, self.line, self.col = detail, line, col
        super().__init__(f'{detail} at line {line} column {col}')


def yaml_debug(v):
    if v is None: return 'Null'
    if isinstance(v, bool): return 'Boolean(' + str(v).lower() + ')'
    if isinstance(v, int): return f'Integer({v})'
    if isinstance(v, float): return 'Real(' + json.dumps(str(v)) + ')'
    if isinstance(v, str): return 'String(' + json.dumps(v, ensure_ascii=False) + ')'
    if isinstance(v, list): return 'Array([' + ', '.join(map(yaml_debug, v)) + '])'
    if isinstance(v, dict): return 'Hash({' + ', '.join(yaml_debug(k) + ': ' + yaml_debug(w) for k,w in v.items()) + '})'
    return 'BadValue'


def split_flow(s, delim=','):
    out=[]; start=0; quote=None; depth=0; esc=False
    for i,c in enumerate(s):
        if quote:
            if c==quote and not esc: quote=None
            if c=='\\' and not esc: esc=True
            else: esc=False
        elif c in '\"\'': quote=c
        elif c in '[{': depth+=1
        elif c in ']}': depth-=1
        elif c==delim and depth==0:
            out.append(s[start:i]); start=i+1
    out.append(s[start:]); return out


def yaml_scalar(s, line=1):
    s=s.strip()
    # YAML's comments only begin following whitespace.
    if not s: return None
    if s.startswith('"'):
        end=1; esc=False
        while end<len(s):
            if s[end]=='"' and not esc: break
            if s[end]=='\\' and not esc: esc=True
            else: esc=False
            end+=1
        if end==len(s): raise YAMLFailure('while scanning a quoted scalar, found unexpected end of stream',line+1,1)
        q=s[:end+1]
        try:return json.loads(q.replace('\\e','\\u001b').replace('\\0','\\u0000').replace('\\_','\\u00a0'))
        except Exception:return q[1:-1]
    if s.startswith("'"):
        if not s[1:].count("'"): raise YAMLFailure('while scanning a quoted scalar, found unexpected end of stream',line+1,1)
        return s[1:s.rfind("'")].replace("''", "'")
    s=re.split(r'\s+#',s,maxsplit=1)[0].strip()
    if s.startswith('['):
        if not s.endswith(']'): raise YAMLFailure('while parsing a node, did not find expected node content',line+1,1)
        return [yaml_scalar(x,line) for x in split_flow(s[1:-1]) if x.strip()]
    if s.startswith('{'):
        if not s.endswith('}'): raise YAMLFailure("while parsing a flow mapping, did not find expected ',' or '}'",line+1,1)
        d={}
        for x in split_flow(s[1:-1]):
            if ':' in x:
                k,v=x.split(':',1);d[yaml_scalar(k,line)]=yaml_scalar(v,line)
        return d
    if s in ('null','Null','NULL','~',''):return None
    if s in ('true','True','TRUE'):return True
    if s in ('false','False','FALSE'):return False
    if re.fullmatch(r'[-+]?\d+',s):
        try:return int(s)
        except ValueError: pass
    if re.fullmatch(r'[-+]?0x[\da-fA-F]+',s):return int(s,16)
    if re.fullmatch(r'[-+]?0o[0-7]+',s):return int(s,8)
    if re.fullmatch(r'[-+]?(?:\d+\.\d*|\d*\.\d+|\d+[eE][-+]?\d+)',s):
        try:return float(s)
        except ValueError:pass
    if re.search(r':\s',s):
        k,v=re.split(r':\s+',s,1);return {yaml_scalar(k,line):yaml_scalar(v,line)}
    return s


def yaml_mapping(text):
    lines=text.splitlines(); out={}; i=0; first=True
    while i<len(lines):
        l=lines[i]; i+=1
        if not l.strip() or l.lstrip().startswith('#') or l.strip() in ('---','...'):continue
        m=re.match(r'^([^:]+):(?:\s+(.*)|$)',l)
        if not m:
            if first:return yaml_scalar('\n'.join(lines).strip())
            raise YAMLFailure('while parsing a block mapping, did not find expected key',i,1)
        first=False;k=yaml_scalar(m.group(1));v=m.group(2) or ''
        if v.strip() in ('|','|-','|+','>','>-','>+'):
            block=[]
            while i<len(lines) and (lines[i].startswith((' ','\t')) or not lines[i]):
                block.append(lines[i]);i+=1
            nonempty=[len(x)-len(x.lstrip()) for x in block if x.strip()];ind=min(nonempty) if nonempty else 0
            parts=[x[ind:] for x in block]
