            if v.endswith('-'):val=val.rstrip('\n')
            else:val=val.rstrip('\n')+'\n'
        elif not v.strip() and i<len(lines) and re.match(r'\s+-\s',lines[i]):
            val=[]
            while i<len(lines) and re.match(r'\s+-\s',lines[i]):
                val.append(yaml_scalar(re.sub(r'^\s+-\s+','',lines[i]),i+1));i+=1
        elif not v.strip() and i<len(lines) and lines[i].startswith(' '):
            block=[]
            while i<len(lines) and (lines[i].startswith(' ') or not lines[i].strip()):block.append(lines[i]);i+=1
            n=min([len(x)-len(x.lstrip()) for x in block if x.strip()] or [0]);val=yaml_mapping('\n'.join(x[n:] for x in block))
        else:
            if v.strip().startswith(('[','{')) and not v.rstrip().endswith((']', '}')):
                vv=v
                while i<len(lines) and not vv.rstrip().endswith((']', '}')):vv+=' '+lines[i].strip();i+=1
                if not vv.rstrip().endswith((']', '}')):raise YAMLFailure('while parsing a node, did not find expected node content',len(lines)+1,1)
                val=yaml_scalar(vv,i)
            else: val=yaml_scalar(v,i)
        out[k]=val
    return out if not first else None


class TemplateError(BookError):
    pass


def template_error(text, pos, expr, reason='not found in this scope', parsing=False):
    line=text.count('\n',0,pos)+1; start=text.rfind('\n',0,pos)+1; col=pos-start+1
    content=text.splitlines()[line-1] if text.splitlines() else ''
    kind='syntax error' if parsing else 'render error'
    raise TemplateError(f'Error compiling template: {kind}\n\n  --> <anonymous>:{line}:{col}\n   |\n {line} | {content}\n   | '+ ' '*(col-1) + '^'*max(1,len(expr))+'\n   |\n   = reason: '+reason+'\n')


def template(text, values, tex=False):
    """Render the small declarative language supported by book templates."""
    if tex:
        text=text.replace('<<','{{').replace('>>','}}').replace('<#','{%').replace('#>','%}')
    tokens=[];last=0
    for m in re.finditer(r'{{[\s\S]*?}}|{%[\s\S]*?%}|{#[\s\S]*?#}',text):
        if m.start()>last:tokens.append(('text',text[last:m.start()],last))
        tokens.append(('var' if m.group().startswith('{{') else 'tag' if m.group().startswith('{%') else 'comment',m.group()[2:-2].strip(),m.start()))
        last=m.end()
    tokens.append(('text',text[last:],last))
    def atom(exp):
        exp=exp.strip()
        if exp.startswith('not '):return not bool(atom(exp[4:]))
        if ' or ' in exp:return any(bool(atom(x)) for x in exp.split(' or '))
        if ' and ' in exp:return all(bool(atom(x)) for x in exp.split(' and '))
        if exp.startswith(('"',"'")):return yaml_scalar(exp)
        if exp in ('true','false'):return exp=='true'
        if exp in values:return values[exp]
        if re.fullmatch(r'[-+]?\d+',exp):return int(exp)
        return None
    def evaluate(exp):
        parts=[x.strip() for x in exp.split('|')];val=atom(parts[0])
        for part in parts[1:]:
            name,_,arg=part.partition(':');a=atom(arg.strip()); name=name.strip()
            if name in ('eq','equals'):val=val==a
            elif name=='ne':val=val!=a
            elif name=='default' and not val:val=a
            elif name=='upper':val=str(val).upper()
            elif name=='lower':val=str(val).lower()
            elif name=='length':val=len(val or '')
            elif name in ('safe','raw'):pass
        return val
    def render_seq(i,active=True):
        pieces=[]
        while i<len(tokens):
            typ,s,pos=tokens[i]
            if typ=='tag' and (s in ('else','endif','endfor') or s.startswith('elif ')):return ''.join(pieces),i
            if typ=='tag' and s.startswith('if '):
                cond=bool(evaluate(s[3:]));body,i=render_seq(i+1,active and cond)
                pieces.append(body)
                while i<len(tokens) and tokens[i][1].startswith('elif '):
                    newcond=not cond and bool(evaluate(tokens[i][1][5:]));body,i=render_seq(i+1,active and newcond);pieces.append(body);cond=cond or newcond
                if i<len(tokens) and tokens[i][1]=='else':
                    body,i=render_seq(i+1,active and not cond);pieces.append(body)
                i+=1;continue
            if typ=='var' and active:
                v=evaluate(s)
                if v is None:
                    vp=pos+2
                    while vp<len(text) and text[vp].isspace():vp+=1
                    template_error(text,vp,s)
                if isinstance(v,bool):v=str(v).lower()
                pieces.append(str(v))
            elif typ=='text' and active:pieces.append(s)
            i+=1
        return ''.join(pieces),i
    return render_seq(0)[0]
