        HTMLRenderer(book,'html.dir').render_directory(path)
        return
    if fmt=='pdf':
        # The default PDF pipeline needs an external TeX engine.
        from tex_renderer import TeXRenderer
        TeXRenderer(book).render()
        raise BookError(f"Error during temporary files editing: failed to run command '{book.opts.get('tex.command','xelatex')}'")
    file=None
    if not stream:
        try:file=open(path,'wb')
        except OSError as e:raise BookError(f"could not create file '{path}': '{e.strerror} (os error {e.errno})")
