    message='Succesfully generated '+name
    if not stream:message+=': '+os.path.relpath(os.path.abspath(path))
    book.log('INFO',message)


def panic(where,message):
    sys.stderr.write(f"\nthread 'main' ({os.getpid()}) panicked at {where}:\n{message}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
    raise SystemExit(101)


def main():
    try:cli=parse(sys.argv[1:])
    except CLIError as e:sys.stderr.write(str(e));return 2
    if not cli.get('quiet'):print(('🐦 CROWBOOK 📚' if cli.get('force-emoji') else 'CROWBOOK')+' 0.17.0',file=sys.stderr)
    try:
        if cli.get('list-options'):
