        if 'create' in cli:create(cli);return 0
        if 'book' not in cli:raise BookError('You must pass the name of a book configuration file.\nFor more information try --help.\n')
        b=Book(cli);b.load()
        if cli.get('autograph'):
            print('Enter autograph:',flush=True);b.opts['autograph']=sys.stdin.readline().strip()
        if cli.get('stats'):
            if not b.chapters:panic('src/lib/stats.rs:285:14','called `Option::unwrap()` on a `None` value')
            sys.stdout.write(b.stats());return 0
        if 'to' in cli:render_one(b,cli['to'],file_destination(b,cli['to'],True))
        else:
            # Auto-named outputs derive from the configuration's basename.
            auto=b.opts.get('output',[])
            basename=os.path.splitext(os.path.basename(b.path))[0]
            for fmt in auto:
                b.opts.setdefault('output.'+fmt,basename+('' if fmt=='html.dir' else '.'+fmt))
            for fmt in ['tex','html','epub','pdf','html.dir']:
                if 'output.'+fmt in b.opts:
                    try:render_one(b,fmt,file_destination(b,fmt,False))
                    except BookError as e:b.log('ERROR',f'Error rendering {fmt}: {e}')
        return 0
    except BookError as e:
        print('ERROR '+str(e),file=sys.stderr);return 0


if __name__=='__main__':
